  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kaeorn.com/program/ambassador', 'official_site', 'compensation', 'KAEORN''s own ambassador page states ''No cap on earnings'' (shown with the infinity symbol) and publishes tiered commission: 10% for 0-10 sales, 15% for 11-50 sales, 20% for 51+ sales, plus a 50% ambassador discount and a personal creator code giving the audience 10% off; commissions are paid monthly with no minimum threshold.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kaeorn.com/program/ambassador', 'official_site', 'ugc_collab', 'The same page sets application requirements: follow @kaeorn.co on Instagram, have personally used at least one Kaeorn fragrance, and post 1 Reel + 2 Stories at launch; applications are reviewed personally within 48 hours, and ambassador content may be reposted and used by the brand across its site, socials and ads with credit.', 'verified', now());
