  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 17, 12, 8, 3, '{"compensation": "Verified uncapped earnings on the brand''s own page with published tiers of 10/15/20% and monthly payouts with no minimum threshold.", "contact_access": "Open application form on the official program page plus a published program email (kaeornwellness@gmail.com).", "credibility": "Very small, young brand (five fragrances, ~150 wearers per its own site), so track record is thin despite the strong published terms.", "niche_fit": "Pure fragrance brand in the beauty niche; scent content is a proven creator category, though narrower than skincare/makeup.", "opportunity_availability": "Applications are publicly open now and reviewed within 48 hours per the program page.", "ugc_evidence": "A structured ambassador program built around creator Reels and Stories, with brand reuse rights for ambassador content across ads and socials."}'::jsonb);
