  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://joskn.com/pages/affiliate-programs', 'official_site', 'ugc_collab', 'The same page describes ambassador perks including early access to product drops and content briefs, a private ambassador email community, and chances to be featured on JOSKN''s socials and website.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://joskn.com/', 'official_site', 'general', 'JOSKN''s homepage describes it as ''a small, family-run UK skincare brand'' founded by Joshua Osinaike with co-founder Aziza Williams, sourced in Ghana and made in the UK, with GBP pricing; its FAQ publishes admin@joskn.com.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 14, 12, 8, 3, '{"compensation": "Published tiers of 10/15/20% on the brand''s own page (10% base recorded); no cap statement, so cap stays unknown.", "contact_access": "Open application page on the official site plus a published email (admin@joskn.com).", "credibility": "Small, young family-run brand - genuine but with a limited track record so far.", "niche_fit": "Pure skincare aimed at melanin-rich skin and everyday concerns - a focused, underserved creator niche.", "opportunity_availability": "Ambassador applications are publicly open via the brand''s own page (UpPromote).", "ugc_evidence": "A structured three-tier ambassador program on the brand''s own page with PR drops, content briefs and social/website features for ambassadors."}'::jsonb);
