  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 10, 6, 5, 7, 5, '{"compensation": "Rate could not be verified: Lasso lists 8% via FlexOffers while Shopper quotes 5%, so it is recorded as null and scored low.", "contact_access": "No public creator email found; access runs through the FlexOffers programme.", "credibility": "Est\u00e9e Lauder brand selling since 1990 with global retail distribution.", "niche_fit": "Iconic plant-based skincare brand - near-perfect fit for skincare and clean-beauty creators.", "opportunity_availability": "Affiliate programme joinable via FlexOffers, subject to approval.", "ugc_evidence": "A network affiliate programme plus an affiliate partner page on the brand''s own site; no open ambassador application was found."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('QuickOnwardTicket', 'https://www.quickonwardticket.com', 'Travel service that issues real, verifiable airline reservations (genuine PNRs) travelers use as proof of onward travel for visa applications and border checks. Its affiliate program pays creators and publishers 25% of every referred sale, tracked over a 60-day cookie, with monthly PayPal/bank payouts from a $50 minimum.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, 25, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.quickonwardticket.com/affiliate.', 'https://www.quickonwardticket.com/affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'QuickOnwardTicket Affiliate Program', 'https://www.quickonwardticket.com/affiliate', 'https://www.quickonwardticket.com/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.quickonwardticket.com/affiliate', 'official_site', 'affiliate', 'Own affiliate page: 25% commission on every referred sale, 60-day cookie window, $50 minimum payout, monthly payouts via PayPal/bank, free to join with quick approval. UNCAPPED verbatim — FAQ ''How much can I earn?'': ''You earn 25% of the sale value on every booking made through your referral link. There''s no cap — the more you refer, the more you earn.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.quickonwardticket.com/affiliate', 'official_site', 'ugc_collab', 'Page explicitly targets travel bloggers, digital-nomad communities, visa consultants, travel agencies, YouTubers & creators and community admins; application is by email with a short note about your audience or channel (the page''s published contact email was masked in the fetched text, so no address is recorded).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 16, 19, 8, 9, 3, '{"niche_fit": "Pure travel utility \u2014 proof of onward travel is a recurring need for the exact audiences travel creators serve.", "ugc_evidence": "Program page names YouTubers & creators, travel bloggers and communities as its target partners.", "compensation": "Published 25% of sale value AND verified uncapped on the brand''s own page (''There''s no cap'').", "contact_access": "Application is by email from the program page; no readable public address could be captured, so none is recorded.", "opportunity_availability": "Open, free application with quick approval; monthly payouts from a $50 threshold.", "credibility": "Small, newer service still describing an early-access phase for affiliate stats; product itself is verifiable (real PNRs)."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Flightright', 'https://www.flightright.com', 'Air passenger rights service founded in 2010 that enforces EU261 compensation (up to £520 / €600) for delayed, cancelled or overbooked flights on a no-win-no-fee basis (success fee typically 20-30% plus VAT). Its affiliate programme on Awin pays a flat £20 CPA per lead/order with a 30-day cookie, and is active in Germany, France and the United Kingdom.', 'Germany', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'partner@flightright.de', null, 'https://ui.awin.com/merchant-profile/15874', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/15874.', 'https://ui.awin.com/merchant-profile/15874', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Flightright Affiliate Programme (Awin)', 'https://ui.awin.com/merchant-profile/15874', 'https://ui.awin.com/merchant-profile/15874', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/15874', 'affiliate_network', 'affiliate', 'Awin merchant profile (fetched): ''Commission: £20 CPA per Lead'', ''A handsome CPA of £20 per order'', 30-day cookie duration. Flat CPA bounty, so commission_rate is null and the £20 flat amount is recorded here. Accepted partner types include ''Content creators & influencers'' and editorial content. Programme active in Germany, France and the United Kingdom.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/15874', 'affiliate_network', 'contact', 'Awin profile closes with ''For campaign questions: partner@flightright.de'' from the Flightright Affiliate Team.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/15874', 'affiliate_network', 'general', 'Profile states Flightright has enforced more than €700 million in compensation since 2010, achieves a 99% success rate in court, and is the market leader in air passenger rights; customer success fee typically 20%-30% plus VAT.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 12, 12, 8, 5, '{"niche_fit": "Flight disruption help is a core travel-creator topic; compensation amounts are concrete and content-friendly.", "ugc_evidence": "Awin profile lists content creators & influencers and communities/UGC among accepted partner types.", "compensation": "Flat \u00a320 CPA per lead/order (recorded as a flat bounty, rate null) \u2014 strong per-action pay but not a % of sale; no cap statement published.", "contact_access": "Named affiliate team email (partner@flightright.de) published on the network profile.", "opportunity_availability": "Open application through Awin, limited to the DE/FR/UK programmes.", "credibility": "Market leader since 2010 with \u20ac700M+ enforced and a 99% court success rate, per its Awin profile."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('WayAway', 'https://wayaway.com', 'Travel metasearch service comparing flights, hotels, car rentals and attractions across hundreds of airlines and agencies, known for WayAway Plus, a paid membership that pays members real-money cashback on bookings. Its affiliate program runs on Travelpayouts: affiliates earn a revenue share on flight bookings plus a fixed bounty per WayAway Plus membership sold.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Travelpayouts', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://uppromote.com/affiliate-directory/wayaway/.', 'https://uppromote.com/affiliate-directory/wayaway/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'WayAway Affiliate Program (via Travelpayouts)', 'https://uppromote.com/affiliate-directory/wayaway/', 'https://uppromote.com/affiliate-directory/wayaway/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blog-staging.travelpayouts.com/wayaway-girltakesmundo/', 'affiliate_network', 'affiliate', 'Travelpayouts (the network hosting the program) states the WayAway partner program rates: flight ticket bookings pay 50% of the revenue share WayAway receives (website cookie 30 days; mobile app installs linked for 180 days), and WayAway Plus sales pay a fixed reward of $10 per sale of the $49.99 membership plan. Revenue-share basis, so commission_rate is null and the structure is recorded here.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/wayaway/', 'listing', 'affiliate', 'UpPromote''s affiliate directory confirms the program is run by Travelpayouts, is CPS/revenue-share plus a fixed rate per membership sale, with a 30-day website cookie and 180-day app attribution; flights average roughly 1.1% to 1.3% of ticket price to the affiliate via the 50% revenue share.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.phocuswire.com/wayaway-cashback-membership', 'listing', 'general', 'PhocusWire coverage: WayAway emerged from Travelpayouts; partners receive up to 50% of the income WayAway receives from airline ticket sales plus $10 per WayAway Plus membership sale.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 13, 5, 9, 4, '{"niche_fit": "Flight/hotel metasearch plus a cashback membership is squarely travel-creator territory.", "ugc_evidence": "Program is marketed to travel content creators through Travelpayouts, with links, widgets, banners and promo codes.", "compensation": "50% revenue share of WayAway''s flight income (about 1.1-1.3% of ticket price) plus a flat $10 per Plus membership; no cap statement published, so cap is unknown and rate is null (revenue-share basis).", "contact_access": "No public program email found on the fetched sources; support runs through the Travelpayouts dashboard.", "opportunity_availability": "Open to join via a free Travelpayouts account; 30-day web cookie and 180-day app attribution.", "credibility": "Established metasearch brand from the Travelpayouts group, covered by PhocusWire."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Chicwish', 'https://www.chicwish.com', 'Online women''s fashion retailer known for feminine dresses, skirts, knitwear and occasion pieces, selling and shipping worldwide in USD with major markets in the US, Canada, Europe, Australia and Asia. Its affiliate program pays 8% commission on referred sales with a 30-day tracking cookie and explicitly also works with fashion bloggers.', null, 'published') returning id into bid;
