  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/88239', 'affiliate_network', 'affiliate', 'Awin-hosted Chicwish program profile (fetched): ''8% commission rate with $90 average order size (commission rate is the SAME if coupons are used and is the SAME for returning customers)'', 30-day tracking cookie, datafeed and banners, dedicated program management, affiliates accepted from every country, and ''We also work with fashion bloggers''. The profile states tracking, sales and payments are handled by ShareASale, which is recorded as the network.', 'verified', now());
