  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 13, 6, 9, 4, '{"niche_fit": "Pure women''s fashion with strong dress/occasionwear content angles for fashion creators.", "ugc_evidence": "Program profile explicitly says it works with fashion bloggers; banners and product feeds supplied.", "compensation": "Published flat 8% on all sales (same rate for coupon and returning-customer orders) on a $90 average order; no cap statement, so cap is unknown.", "contact_access": "Dedicated program management via the network, but no public email on the fetched profile.", "opportunity_availability": "Open network application; affiliates accepted from every country.", "credibility": "Long-running global retailer with a detailed, current network program profile."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FlyClaim', 'https://www.flyclaim.eu', 'Flight compensation service that pursues EU Regulation 261/2004 claims (up to €600 per passenger) for delayed, cancelled or disrupted flights on a success-fee basis. Its partner program pays affiliates 15% of FlyClaim''s success fee on every referred claim that pays out, with 30-day tracking, monthly payouts and no minimum volume.', null, 'published') returning id into bid;
