  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flyclaim.eu/affiliates', 'official_site', 'affiliate', 'Own affiliate page (fetched): ''You keep 15% of our fee'' — for every successful claim credited within the 30-day cookie window the partner receives 15% of FlyClaim''s success fee, paid monthly; typical partner earnings €50+ per successful claim. Percentage-of-fee (revenue) basis, so commission_rate is null and the basis is recorded here. No contracts, no quotas, no minimum volume.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flyclaim.eu/affiliates', 'official_site', 'ugc_collab', 'Page names creators first among who it suits (''Travel voices on TikTok, Instagram, YouTube or in a newsletter''), plus publishers, travel tools and networks; application is a short form on the page, no website required.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 13, 6, 9, 3, '{"niche_fit": "Flight-delay compensation is a narrower travel niche than booking, but highly relevant to frequent-flyer audiences.", "ugc_evidence": "Program page leads with creators on TikTok, Instagram and YouTube and supplies ready-to-use assets.", "compensation": "15% of the service''s success fee per paid claim (revenue basis, rate null), typically \u20ac50+ per claim; no cap statement published.", "contact_access": "Application form on the program page with a named partner contact promised after approval; no public email recorded.", "opportunity_availability": "Open application, no contract, no minimum volume, monthly payouts.", "credibility": "Smaller, newer claims service; terms are clearly published on its own page."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Farm Rio', 'https://www.farmrio.com', 'Brazilian fashion and lifestyle brand founded in Rio de Janeiro, known for bold tropical prints and colorful women''s clothing, with stores and e-commerce in Brazil, the US and Europe. Its affiliate program runs on Rakuten Advertising and pays 5% per sale with a 30-day cookie.', 'Brazil', 'published') returning id into bid;
