  insert into public.brands (name, website, description, country, status) values ('BAGGU', 'https://www.baggu.com', 'San Francisco-based bag and accessories brand best known for its reusable Standard Baggu shoppers, plus totes, backpacks, pouches and travel bags in seasonal prints, built around sustainability and recycled materials. Its affiliate program runs on Pepperjam (Ascend) and pays 5-10% per sale with a 30-day cookie.', 'United States', 'published') returning id into bid;
