  insert into public.brands (name, website, description, country, status) values ('Keepgo', 'https://www.keepgo.com', 'Global connectivity provider selling prepaid travel eSIMs, data SIM cards and WiFi hotspots covering 100+ countries, aimed at travelers who want data without roaming fees. Its affiliate partner program pays a percentage of every sale and refill through a unique link, with a 30-day cookie and monthly PayPal payouts; the exact rate is agreed individually with each partner.', null, 'published') returning id into bid;
