  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/lola/', 'third_party_listing', 'commission_rate_conflict', 'RATE CONFLICT — commission_rate is recorded as null. The Lasso program listing reports ''up to 15.0%'' with a 14-day cookie and a $10 payout threshold, while the Awin program description for LOLA (via affi.io) describes a flat $3–$5 per order with a 30-day cookie and coupons distributed through Pepperjam. The two sources describe materially different pay structures, so no single rate is recorded.', 'publicly_reported', now());
