  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 11, 5, 6, 6, 4, '{"compensation": "No rate recorded: sources conflict between ''up to 15%'' (Lasso) and a flat $3\u2013$5 per order (Awin program description), so compensation scores low until the brand''s current terms are confirmed.", "contact_access": "Application runs through the network/listing route; no public brand program email was found.", "credibility": "Well-known national women''s health brand with wide retail distribution and its own storefront.", "niche_fit": "Organic period and personal care is a strong fit for women''s health creators and routine content.", "opportunity_availability": "Open application; the conflicting published terms add friction a creator must resolve before promoting.", "ugc_evidence": "A live network affiliate program exists, but no published creator cohort or campaign evidence was found."}'::jsonb);
