  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://store.omadanetworks.com/pages/affiliate-program', 'official_site', 'affiliate', 'Omada''s own store affiliate page states a flat 12% commission on all qualified sales with a 30-day cookie window, applications via Impact (Apply buttons route to app.impact.com), a dedicated affiliate manager, and marketing assets; it explicitly courts YouTube tech reviewers, tech bloggers, and prosumer/smart-home influencers. No earnings-cap statement appears on the page, so the cap is recorded as unknown.', 'verified', now());
