  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 16, 13, 8, 5, '{"compensation": "A flat 12% on all qualified sales with a 30-day cookie, stated on the brand''s own page \u2014 well above typical consumer-tech rates; no cap statement found, so no uncapped credit.", "contact_access": "A published affiliate-program email (affiliate@omadanetworks.com) plus a clear Impact application route on the brand''s own page.", "credibility": "Omada is the business networking line of TP-Link Systems Inc. (Irvine, CA), one of the world''s largest networking brands.", "niche_fit": "Networking hardware (Wi-Fi access points, switches, gateways) is core review content for tech, home-lab and smart-home creators, though it skews prosumer rather than mass consumer.", "opportunity_availability": "Open application via Impact; the brand reviews applications for audience fit, so it is not instant-approval.", "ugc_evidence": "The brand''s own affiliate page names the creator types it wants \u2014 YouTube tech reviewers, tech bloggers, smart-home influencers \u2014 and supplies banners, logos and product links."}'::jsonb);
