  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 14, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by http://www.businesswire.com/news/home/20250218481955/en/Pebblebee-Launches-Creative-Collective-to-Offer-Creators-Unmatched-Rewards.', 'https://pebblebee.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Pebblebee Creator Collective', 'https://pebblebee.com/', 'http://www.businesswire.com/news/home/20250218481955/en/Pebblebee-Launches-Creative-Collective-to-Offer-Creators-Unmatched-Rewards', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'http://www.businesswire.com/news/home/20250218481955/en/Pebblebee-Launches-Creative-Collective-to-Offer-Creators-Unmatched-Rewards', 'press_release', 'affiliate', 'Pebblebee''s February 2025 Business Wire launch release for its Creator (Creative) Collective: Rising Star tier pays 18% commission for the first 1,000 influencers, then 14% ongoing, plus a free Clip or Card, early product access, an exclusive influencer Slack channel and a 15% follower discount code; Elite Creator tier (auto-upgrade after 50 orders or $10,000 revenue) pays 22.5% for the first 50 qualifiers, then 20%. Over 200 payout methods (PayPal, Venmo, gift cards, charity). Sign-up is via the Creator Collective page on pebblebee.com. The recorded rate is the ongoing 14% Rising Star rate. No earnings-cap statement is made, so the cap is unknown; the tier slot limits are rate cohorts, not a stated current creator count, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pebblebee.com/', 'official_site', 'general', 'Pebblebee''s homepage states it designed one of the first personal Bluetooth trackers in 2013, is located just outside Seattle, has sold millions of units with 30+ patents filed, and its Universal line is a CNN Underscored Top Pick; trackers work with Apple Find My and Google''s Find Hub and recharge about once a year.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 17, 5, 7, 5, '{"compensation": "14% ongoing Rising Star commission (18% launch cohort), rising to 20-22.5% at Elite, plus free product \u2014 top-tier consumer-tech pay; rates come from the Feb 2025 launch release, so current slot status is unverified.", "contact_access": "No public partnerships email found on the fetched pages; the only route is the sign-up form on the brand''s site.", "credibility": "Operating since 2013 with millions of units sold, 30+ patents and national press coverage (CNN Underscored, ZDNet, The Verge).", "niche_fit": "Item trackers are natural tech, travel and everyday-carry content, and the program is designed for Instagram, TikTok and YouTube creators.", "opportunity_availability": "Open sign-up form on pebblebee.com, but the highest-rate cohorts are slot-limited (first 1,000 / first 50) and may be filled.", "ugc_evidence": "A creator-first program with its own tiers, free product, early access, a private influencer Slack channel and follower discount codes \u2014 strong structured UGC evidence from the brand''s own launch release."}'::jsonb);
