  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Real Dog Box Affiliate Program', 'https://real.dog/affiliate', 'https://real.dog/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://real.dog/affiliate', 'official_site', 'affiliate', 'Real Dog Box''s own affiliate page: earn up to 30% on the first box or 10% on the next six boxes, free to join, affiliates get a complimentary Wellness Membership ($22/month value), milestone rewards, a unique short referral link and a real-time dashboard; affiliates must maintain at least three sign-ups per 28-day period to stay active, and paid-search promotion is excluded. The recorded rate is the 30% first-box rate. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://real.dog/affiliate', 'official_site', 'general', 'The same page states the brand is based in San Diego, California, crafts its treats in small batches in its San Diego kitchen, and features an affiliate success story (a promoter reporting over $5,200 earned).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 18, 6, 8, 4, '{"compensation": "Up to 30% on the first box and 10% on the next six boxes per the brand''s own page, plus a free $22/month Wellness Membership \u2014 among the strongest pet rates found; no cap statement, so no uncapped credit.", "contact_access": "Application runs through the brand''s own affiliate page; no public partnerships email was published on the fetched page.", "credibility": "Established San Diego DTC brand with its own kitchen and a published affiliate track record, though smaller than national pet brands.", "niche_fit": "Fresh single-ingredient dog treats are highly demonstrable pet-niche content (unboxings, feeding routines, treat reviews).", "opportunity_availability": "Free, open application on the brand''s site; staying active requires three sign-ups per 28 days, a modest activity bar.", "ugc_evidence": "The program page targets website owners, content creators, health influencers and bloggers, and publishes an affiliate success story and milestone rewards."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('HydroJug', 'https://www.thehydrojug.com', 'Ogden, Utah hydration brand founded by brothers Hayden and Jake Wadsworth, known for its 73oz half-gallon water jugs and an expanded line of tumblers, travelers, sleeves and carriers, sold DTC and through retailers including Target, Scheels and Dick''s Sporting Goods.', 'United States', 'published') returning id into bid;
