  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'HydroJug TikTok Shop Affiliate', 'https://www.thehydrojug.com/pages/ambassadors-affiliates', 'https://www.thehydrojug.com/pages/ambassadors-affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.thehydrojug.com/pages/ambassadors-affiliates', 'official_site', 'affiliate', 'HydroJug''s own Ambassadors & Affiliates page routes creators to TikTok Shop''s affiliate program: join via TikTok creator tools, request HydroJug products in the affiliate marketplace, tag products in videos/LIVEs/showcases and earn commission on every sale, with tracking and payouts handled by TikTok. Commission is set per product inside TikTok Shop and varies, so no single rate can be recorded (commission_rate null). The brand states there is no follower minimum from its side. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.zoominfo.com/c/hydrojug-llc/445798972', 'listing', 'general', 'ZoomInfo lists HydroJug LLC headquarters in Ogden, Utah, describing it as a hydration and drinkware company founded by brothers Hayden and Jake Wadsworth, selling reusable half-gallon jugs, tumblers, travelers, lids, straws and sleeves DTC and through retail stores.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 9, 6, 9, 5, '{"compensation": "Commission is real but set per product inside TikTok Shop and not published on the brand''s page, so the level cannot be verified from a fetched source \u2014 mid-low score despite the program being genuine.", "contact_access": "The brand page explains the full join path, but contact is mediated entirely through TikTok Shop; no brand email is published.", "credibility": "Fast-growing national brand (Inc. 5000-listed growth) with headquarters in Ogden, Utah and placement in major US retailers.", "niche_fit": "Half-gallon jugs and tumblers are staple hydration, gym and day-in-the-life content across TikTok and Instagram.", "opportunity_availability": "Open to all TikTok creators with no follower minimum from the brand''s side \u2014 only TikTok Shop''s own regional eligibility applies.", "ugc_evidence": "The brand''s own page is a creator playbook \u2014 it names the content formats that perform (reviews, GRWM, gym content, vlogs, unboxings) and runs its affiliate route natively inside TikTok."}'::jsonb);
