  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://dinovite.com/pages/affiliate', 'official_site', 'affiliate', 'Dinovite''s own affiliate page invites creators to apply (Apply buttons route to compana.everflowclient.io, the Everflow platform of parent Compana Pet Brands) and states ''30% commission on every successful sale'', with resources and brand guidelines for affiliates. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/dinovite/', 'affiliate_network', 'compensation', 'RATE CONFLICT: Lasso''s directory lists the Dinovite program at 10% per sale with a 7-day cookie, joining via ShareASale — conflicting with the 30% stated on the brand''s own current affiliate page (which routes applications to Everflow). Because sources conflict, commission_rate is recorded as null; the brand page suggests the program may have moved networks, but the current payable rate needs confirmation.', 'needs_review', now());
