  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 8, 6, 8, 4, '{"compensation": "Headline pay could be strong (30% on the brand''s own page) but a directory lists 10% via a different network, so the rate is unverified and recorded as null \u2014 score held down until confirmed.", "contact_access": "Open application on the brand''s own page via Everflow; no public partnerships email found.", "credibility": "25+ years in market and over a million pets helped per the brand, now backed by Compana Pet Brands; the conflicting rate listings keep this below top marks.", "niche_fit": "Dog and cat supplements for skin, coat and digestion are a core pet-creator niche with clear before/after content angles.", "opportunity_availability": "Publicly open application welcoming beginners as well as seasoned affiliates.", "ugc_evidence": "The brand''s own page is written for bloggers, social media influencers, YouTube creators and small businesses, with resources and brand guidelines supplied."}'::jsonb);
