  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'NaturVet Affiliate Program', null, 'https://getlasso.co/affiliate/naturvet/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/naturvet/', 'affiliate_network', 'affiliate', 'Lasso''s affiliate directory lists the NaturVet program at up to 11.25% commission with a 14-day cookie, a $10 payout threshold, no approval requirements, and the network listed as Lasso (product links route to app.getlasso.co; the 11.25% figure has the look of a marketplace-derived rate, so it is single-source and recorded as publicly reported). ''Up to 11.25%'' is a rate ceiling, not an earnings cap — no no-cap statement exists, so the cap is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://storage.mfn.se/55bb483c-8d36-493b-9e8d-b74496e42bd3/swedencare-ab-publ-acquires-leading-american-pet-supplement-company-naturvet.pdf', 'press_release', 'general', 'Swedencare''s acquisition release describes NaturVet (Garmon Corp.), founded in 1994, as a premium US pet healthcare company with in-house development and production in Temecula, California, products in about twenty categories sold to over 15,000 US pet shops and online platforms.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 12, 4, 9, 5, '{"compensation": "Up to 11.25% per the directory with a low $10 payout threshold; the short 14-day cookie and single-source rate keep this mid-range.", "contact_access": "No public affiliate contact or brand application page found; joining runs through Lasso only.", "credibility": "In business since 1994, manufactured in its own California facilities, sold in 15,000+ US pet shops and owned by listed pet-health group Swedencare.", "niche_fit": "Mainstream pet supplements (calming, joint, digestive) map directly onto pet-owner content and problem/solution videos.", "opportunity_availability": "Directory lists no approval requirements \u2014 effectively open enrollment through Lasso.", "ugc_evidence": "The program is listed for pet bloggers and creators in Lasso''s directory, but no brand-run creator program or UGC campaign evidence was found on the brand''s own pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bio Bidet', 'https://biobidet.com', 'Bio Bidet by Bemis sells bidet toilet seats, attachments and smart toilets (Bliss BB-2000, BB-900, Discovery DLS) with heated seats, warm-water wash and air drying, positioned as a DIY-install bathroom upgrade; its BB-2000 was voted Forbes'' Best Bidet Overall for 2025 and 2026.', 'United States', 'published') returning id into bid;
