  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://biobidet.com/', 'official_site', 'general', 'Bio Bidet''s homepage sells bidet seats and smart toilets from $189 to $699 with DIY installation in about 20 minutes, advertises free shipping on orders of $199+ in the contiguous US, and carries the ''Forbes Voted Best Bidet Overall 2025 & 2026'' badge.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 11, 10, 5, 7, 5, '{"compensation": "5% per sale is modest, but on $189-$699 seats it yields meaningful per-order payouts, with a standard 30-day cookie.", "contact_access": "Application runs through Impact via the directory join route; the brand publishes phone and a contact form but no affiliate email.", "credibility": "The bidet line of Bemis, a long-established US bathroom brand, with Forbes Best Bidet Overall honors for 2025 and 2026.", "niche_fit": "Bidets are a proven home-upgrade content niche (install videos, bathroom makeovers, hygiene routines) with high product prices.", "opportunity_availability": "Open application on Impact, subject to the network''s standard approval.", "ugc_evidence": "The program is marketed to bloggers and home-improvement creators in the directory listing, but no brand-run creator program evidence was found on the brand''s own pages."}'::jsonb);
