  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 10, 4, 7, 5, '{"compensation": "5% per sale across all products with a 30-day cookie \u2014 standard home-decor economics on affordable price points.", "contact_access": "No public affiliate email or dedicated program page found; the join route is via the brand''s site from the directory listing.", "credibility": "Global design brand founded in 1979, headquartered in Toronto and distributed in over 120 countries.", "niche_fit": "Design-led everyday housewares are highly visual home-decor content \u2014 organization, small-space and room-refresh videos.", "opportunity_availability": "Open application per the directory, with approval typically taking a few days.", "ugc_evidence": "The directory positions the program for bloggers, content creators and home enthusiasts; no brand-run creator program was verified on the brand''s own pages."}'::jsonb);
