  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.rakwireless.com/en-us/legal/affiliate-program-terms', 'official_site', 'affiliate', 'RAKwireless'' own Affiliate Program Terms (last updated May 20, 2025): affiliates sign up through the GoAffPro platform and earn 5% commission on the total sale (excluding shipping, duties and taxes) for purchases in the RAKwireless Store; links carry a 180-day assigned duration, commissions face a 30-day review period, payout is via PayPal on the 1st and 15th of each month with a $20 minimum, self-purchases and PPC bidding are prohibited. No earnings-cap statement appears, so the cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 10, 11, 4, 8, 4, '{"compensation": "5% is modest, but the 180-day link duration is unusually generous and payout terms (PayPal twice monthly, $20 minimum) are fully published in the brand''s own terms.", "contact_access": "Only a general web form is referenced in the terms; no affiliate email or named contact is published.", "credibility": "Established IoT hardware brand with its own store and formally published program terms governed by Hong Kong law.", "niche_fit": "LoRaWAN and IoT hardware serves a focused maker/developer creator niche rather than broad consumer audiences.", "opportunity_availability": "Open sign-up through GoAffPro for anyone 18+ with a PayPal account, per the published terms.", "ugc_evidence": "The terms explicitly allow sharing affiliate links on any social media platform, but there is no creator-specific program, assets or community evidence."}'::jsonb);
