  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 8, 4, 7, 5, '{"compensation": "4% per sale with a short 10-day cookie \u2014 the weakest pay package in this batch, partly offset by $200-$300 product prices.", "contact_access": "No public affiliate contact found; joining runs through FlexOffers only.", "credibility": "Category-defining smart irrigation brand founded in 2012, now owned by irrigation major Rain Bird.", "niche_fit": "Smart irrigation is solid smart-home and lawn/garden content, though seasonal and narrower than indoor tech.", "opportunity_availability": "Open application through FlexOffers, subject to network approval.", "ugc_evidence": "The program is listed for gardening and home bloggers in the directory; no brand-run creator program evidence was found on the brand''s own pages."}'::jsonb);
